                    dx = max(3, int(round((right - left) * 0.1)))
                    dy = max(3, int(round((bottom - top) * 0.1)))
                    box = (left + dx, top + dy, max(left + dx + 1, right - dx), max(top + dy + 1, bottom - dy))
